referenceSolutions.javascript:
export function solve(rows, requirements) {
  return rows.filter((row) =>
    requirements.every(
      (r) =>
        Object.hasOwn(row, r.key) &&
        (r.op === "eq"
          ? row[r.key] === r.value
          : r.op === "gt"
            ? row[r.key] > r.value
            : r.value.includes(row[r.key])),
    ),
  );
}

